def is_valid_email(email):
    # Check if email is not empty
    if not email:
        return False

    # Check if email contains exactly one '@' symbol
    if email.count('@') != 1:
        return False

    # Split email into local and domain parts
    local, domain = email.split('@')

    # Check if local part is not empty
    if not local:
        return False

    # Check if domain part is not empty
    if not domain:
        return False

    # Check if local part does not start or end with '.'
    if local.startswith('.') or local.endswith('.'):
        return False

    # Check if domain part does not start or end with '.'
    if domain.startswith('.') or domain.endswith('.'):
        return False

    # Check if domain contains at least one '.'
    if '.' not in domain:
        return False

    # Check if there are no consecutive dots
    if '..' in email:
        return False

    # Check if email contains only valid characters
    valid_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-")
    if not all(c in valid_chars for c in email):
        return False

    return True

# Example usage:
email = input("Enter an email address: ")
if is_valid_email(email):
    print("Valid email address.")
else:
    print("Invalid email address.")
